'use server'

import { generateReportFeedbackLite } from '@/lib/ai/gemini'
import { log } from '@/lib/observability/logger'

export type AiLikelihoodResult = {
    likelihoodPercentage: number // 0 to 100
    riskLevel: 'LOW' | 'MEDIUM' | 'HIGH'
    indicators: string[]
    reasoning: string
}

/**
 * Evaluates the likelihood (0-100%) that an open-ended candidate response was generated by an AI model.
 * Performs a dual evaluation: heuristic pattern checking + Gemini contra-evaluation.
 */
export async function analyzeAiLikelihood(
    responseText: string,
    questionContext: string
): Promise<AiLikelihoodResult> {
    if (!responseText || responseText.trim().length < 15) {
        return {
            likelihoodPercentage: 0,
            riskLevel: 'LOW',
            indicators: ['Respuesta muy corta para análisis de IA'],
            reasoning: 'Respuesta breve o vacía.'
        }
    }

    const trimmed = responseText.trim()
    const lower = trimmed.toLowerCase()

    // 1. Heuristic Pattern Detection
    const heuristicIndicators: string[] = []
    let baseScore = 5 // Base baseline

    // Typical generative phrases in Spanish LLM responses
    const llmPhrases = [
        'en resumen',
        'es importante destacar',
        'cabe mencionar',
        'por un lado',
        'por otro lado',
        'en conclusión',
        'como modelo de lenguaje',
        'es fundamental tener en cuenta',
        'en primer lugar',
        'en segundo lugar',
        'para abordar este problema',
        'un enfoque estructurado'
    ]

    let phraseMatches = 0
    for (const phrase of llmPhrases) {
        if (lower.includes(phrase)) {
            phraseMatches++
            heuristicIndicators.push(`Uso de fraseología típica de LLM: "${phrase}"`)
        }
    }

    if (phraseMatches >= 3) baseScore += 35
    else if (phraseMatches >= 1) baseScore += 15

    // Overly structured formatting check (excessive bullet points, bold headers in short answers)
    if (trimmed.includes('**') && (trimmed.includes('\n- ') || trimmed.includes('\n1. '))) {
        baseScore += 20
        heuristicIndicators.push('Formato sintáctico hiper-estructurado (negritas y viñetas complejas)')
    }

    // High vocabulary density with zero personal/situational references
    const hasPersonalContext = /\b(en mi experiencia|en nuestro cluster|en el equipo|nos pasó|revisé|ejecuté|probamos|teníamos)\b/i.test(trimmed)
    if (!hasPersonalContext && trimmed.length > 250) {
        baseScore += 10
        heuristicIndicators.push('Ausencia total de jerga situacional o experiencia personal')
    }

    // 2. Gemini Contra-Evaluation Prompt
    const prompt = `Actúa como un Auditor de Integridad de Evaluaciones Técnicas y Especialista en NLP.
Tu tarea es determinar la probabilidad (de 0 a 100) de que la siguiente respuesta técnica escrita por un candidato fue redactada por un modelo de lenguaje de IA (como ChatGPT, Claude o Gemini) en lugar de ser redactada directamente por un ser humano bajo presión de examen.

PREGUNTA DE LA EVALUACIÓN:
"${questionContext}"

RESPUESTA DEL CANDIDATO:
"${responseText}"

INSTRUCCIONES DE EVALUACIÓN:
1. Evalúa si el texto tiene el tono robótico, perfectamente articulado, con listas numeradas o introducciones de libro de texto típicas de IA generativa.
2. Un ingeniero humano suele cometer pequeños errores tipográficos, usar jerga coloquial de SRE (ej. "el pod se cayó", "tiró un 500", "el collector se ahogó"), o escribir de forma directa.
3. Asigna un porcentaje de probabilidad de 0 a 100.
   - 0 - 29: Muy probable escrito por un humano.
   - 30 - 69: Dudoso / Posible asistencia parcial.
   - 70 - 100: Altamente probable generado por IA.

Responde ÚNICAMENTE con un JSON con la siguiente estructura:
{
  "likelihoodPercentage": 75,
  "indicators": ["Fraseología académica impersonal", "Estructura en 3 puntos típica de ChatGPT"],
  "reasoning": "Breve explicación en 1 oración"
}`

    try {
        const raw = await generateReportFeedbackLite(prompt)
        const jsonMatch = raw.match(/\{[\s\S]*\}/)
        const cleaned = jsonMatch ? jsonMatch[0] : raw.replace(/```json/gi, '').replace(/```/g, '').trim()
        const parsed = JSON.parse(cleaned)

        const modelLikelihood = typeof parsed.likelihoodPercentage === 'number' ? parsed.likelihoodPercentage : baseScore
        // Combine model output with heuristic indicators
        const finalPercentage = Math.min(100, Math.max(0, Math.round((modelLikelihood * 0.7) + (baseScore * 0.3))))
        const combinedIndicators = Array.from(new Set([...(parsed.indicators || []), ...heuristicIndicators]))

        let riskLevel: 'LOW' | 'MEDIUM' | 'HIGH' = 'LOW'
        if (finalPercentage >= 70) riskLevel = 'HIGH'
        else if (finalPercentage >= 30) riskLevel = 'MEDIUM'

        return {
            likelihoodPercentage: finalPercentage,
            riskLevel,
            indicators: combinedIndicators,
            reasoning: parsed.reasoning || 'Evaluación contra-analítica de patrón de lenguaje.'
        }
    } catch (error) {
        log.ai.error('Error en analyzeAiLikelihood contra-evaluación', error as Error)
        const finalPercentage = Math.min(100, Math.max(0, baseScore))
        return {
            likelihoodPercentage: finalPercentage,
            riskLevel: finalPercentage >= 70 ? 'HIGH' : finalPercentage >= 30 ? 'MEDIUM' : 'LOW',
            indicators: heuristicIndicators,
            reasoning: 'Análisis heurístico de patrón sintáctico.'
        }
    }
}
